p_play_initkeys_c:		; call initkeys (turbo)
			ld (p_play_initkeys_rs), sp
			ld a, (ntc_ovl_lc)	; called from its own page?
			or a
			jr z, p_play_initkeys_far
			xor a
			ld (ntc_ovl_lc), a
			dec a
			ld (p_play_initkeys_pg), a	; #FF..: no page back on return
			ld (p_play_initkeys_pg+1), a
			jr p_play_initkeys_in
p_play_initkeys_far:
			ld hl, ovl_blk_playp	; page INTRON.003
			ld de, p_play_initkeys_pg
			ld ix, p_play_initkeys_in
			jp ntc_ovl_enter
p_play_initkeys_in:
			ld sp, p_play_initkeys
			ret
p_play_initkeys_r:		; end of initkeys
			ld hl, (p_play_initkeys_pg)
			ld a, h
			and l
