			ld hl, ovl_blk_playp	; page INTRON.003
			ld de, p_screens_pgtx_pg
			ld ix, p_screens_pgtx_in
			jp ntc_ovl_enter
p_screens_pgtx_in:
			ld sp, p_screens_pgtx
			ret
p_screens_pgtx_r:		; end of pgtx
			ld hl, (p_screens_pgtx_pg)
			ld a, h
			and l
			inc a
			jr z, p_screens_pgtx_rb	; a call from its own page: nothing to switch back
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_screens_pgtx_pg)
			call mem_sel
p_screens_pgtx_rb:
			ld sp, (p_screens_pgtx_rs)
			ret
p_screens_showpg_c:		; call showpg (turbo)
			pop hl			; kind
			ld de, var_screens_showpg_kind		; (the block of 2 parameters)
			ldi
			ldi
			pop hl			; p
			ldi
			ldi
			ld hl, 0
			ld (var_screens_showpg_t), hl
			ld (p_screens_showpg_rs), sp
			ld a, (ntc_ovl_lc)	; called from its own page?
			or a
			jr z, p_screens_showpg_far
			xor a
			ld (ntc_ovl_lc), a
			dec a
			ld (p_screens_showpg_pg), a	; #FF..: no page back on return
			ld (p_screens_showpg_pg+1), a
			jr p_screens_showpg_in
p_screens_showpg_far:
			ld hl, ovl_blk_playp	; page INTRON.003
			ld de, p_screens_showpg_pg
			ld ix, p_screens_showpg_in
			jp ntc_ovl_enter
p_screens_showpg_in:
			ld sp, p_screens_showpg
			ret
p_screens_showpg_r:		; end of showpg
			ld hl, (p_screens_showpg_pg)
			ld a, h
			and l
			inc a
			jr z, p_screens_showpg_rb	; a call from its own page: nothing to switch back
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_screens_showpg_pg)
			call mem_sel
p_screens_showpg_rb:
			ld sp, (p_screens_showpg_rs)
			ret
ovl_playp__x_e:
			dw 0			; (never empty)
ovl_playp_end:		; the end of its code; page variables follow
ovl_playp_vsize	equ 0		; its page variables; its local memory is the rest, to #8000
			IF ovl_playp_vsize > 0
			ds ovl_playp_vsize, 0
			ENDIF
			ASSERT ovl_playp_end + ovl_playp_vsize <= #8000, "page PLAYP (play, attack, screens) is more than 16K (code and page variables)"
			DISPLAY "page PLAYP (INTRON.003):"
			DISPLAY "  play ", /D, ovl_playp__0_e - ovl_playp__0_s
			DISPLAY "  attack ", /D, ovl_playp__1_e - ovl_playp__1_s
			DISPLAY "  screens ", /D, ovl_playp__2_e - ovl_playp__2_s
			DISPLAY "  (local entries, stubs) ", /D, ovl_playp__x_e - ovl_playp__x_s
			DISPLAY "  page variables ", /D, ovl_playp_vsize, ", free ", /D, #8000 - (ovl_playp_end + ovl_playp_vsize)
			MMU 2 3, 18		; (the program's own pages back for what follows)

; ============================================================
; ZX Spectrum Next: the start stub (bank 5, page 11 at #7E00) and the NEX file
; ============================================================
			IF NTC_PLATRSV == 0		; (with the platform's #BA00-#FFFF Reserved in the map, the build goes round it)
			ASSERT ntc_free <= #BA00, "the program and its arrays must end below #BA00 (the FileSystem class's DOS area is #BA00-#BDFF, the stack #BE00-#BFFF, the screen #C000-#FFFF)"
			ENDIF

; Option NexData: "INTRO.DAT", 42 blocks of 16K, in their banks
			MMU 0 1, 2
